/* ============================================
   CHECKBOX COMPONENT
   Custom checkbox with check / indeterminate icon
   ============================================ */

.ds-checkbox {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-200); /* 8px */
  cursor: pointer;
  user-select: none;
}

/* ============================================
   BOX
   ============================================ */

.ds-checkbox__box {
  position: relative;
  width: 24px;
  height: 24px;
  box-sizing: border-box;
  border: var(--border-050) solid var(--color-bg-container-border);
  border-radius: var(--radius-200); /* 8px */
  background-color: var(--color-bg-container-primary-transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background-color var(--motion-duration-base) var(--motion-ease-standard), border-color var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   ICON
   ============================================ */

.ds-checkbox__icon {
  width: 14px;
  height: 14px;
  color: var(--color-action-primary-text-active);
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
  display: block;
}

/* ============================================
   LABEL
   ============================================ */

.ds-checkbox__label {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  letter-spacing: var(--font-paragraph-letter-spacing);
  color: var(--color-text-primary);
}

/* Helper line: label and helper stack in a text column beside the box; the
   box aligns to the first text line rather than the column's centre. */
.ds-checkbox--has-helper {
  align-items: flex-start;
}

.ds-checkbox__text {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050); /* 2px */
}

.ds-checkbox__helper {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
}

.ds-checkbox--error .ds-checkbox__helper {
  color: var(--color-status-error-border);
}

/* ============================================
   CHECKED STATE
   ============================================ */

.ds-checkbox--checked .ds-checkbox__box {
  background-color: var(--color-action-primary-bg);
  border-color: var(--color-action-primary-bg);
}

.ds-checkbox--checked .ds-checkbox__icon {
  opacity: 1;
}

/* ============================================
   INDETERMINATE STATE
   ============================================ */

.ds-checkbox--indeterminate .ds-checkbox__box {
  background-color: var(--color-action-primary-bg);
  border-color: var(--color-action-primary-bg);
}

.ds-checkbox--indeterminate .ds-checkbox__icon {
  opacity: 1;
}

/* ============================================
   HOVER STATE
   ============================================ */

.ds-checkbox:not(.ds-checkbox--disabled):hover .ds-checkbox__box {
  border-color: var(--color-action-primary-bg);
}

.ds-checkbox--checked:not(.ds-checkbox--disabled):hover .ds-checkbox__box {
  background-color: var(--color-action-primary-bg-hover);
  border-color: var(--color-action-primary-bg-hover);
}

/* ============================================
   FOCUS STATE
   ============================================ */

.ds-checkbox:focus-visible .ds-checkbox__box {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-checkbox--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-checkbox--compact .ds-checkbox__box {
  width: 20px;
  height: 20px;
}

.ds-checkbox--compact .ds-checkbox__icon {
  width: 12px;
  height: 12px;
}

.ds-checkbox--compact .ds-checkbox__label {
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

/* ============================================
   CHECKBOX GROUP
   ============================================ */

.ds-checkbox-group {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
}

/* The group label is Field's (ds-field__label) — the group composes
   <Field group>, so the scaffolding classes come from Field.css. */

.ds-checkbox-group__items {
  display: flex;
  flex-direction: column;
  gap: var(--gap-200); /* 8px */
}

.ds-checkbox-group--horizontal .ds-checkbox-group__items {
  flex-direction: row;
  gap: var(--gap-500); /* 20px */
}

'use client';

import React, { useId } from 'react';
import { Field } from '../Field/Field';
import './Checkbox.css';

/** Props owned by Checkbox itself — everything else falls through to the wrapper. */
type CheckboxOwnProps = {
  /** Label text */
  label?: string;
  /** Helper or error message rendered under the label text */
  helperText?: string;
  /** Error state — recolours the helper text and marks the checkbox invalid */
  error?: boolean;
  /** Whether the checkbox is checked */
  checked?: boolean;
  /** Whether the checkbox is in an indeterminate state */
  indeterminate?: boolean;
  /** Whether the checkbox is disabled */
  disabled?: boolean;
  /** Component size */
  size?: 'default' | 'compact';
  /** Called with the next checked state when toggled */
  onCheckedChange?: (checked: boolean) => void;
  /** Additional CSS classes */
  className?: string;
  /**
   * Legacy change handler, kept for backwards compatibility.
   *
   * @deprecated Use `onCheckedChange` instead.
   */
  onChange?: (checked: boolean) => void;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
  /**
   * Legacy form-field name.
   *
   * @deprecated No-op. This component renders a `<div role="checkbox">`, not a
   * native `<input>`, so it cannot participate in native form submission.
   * Declared only so the attribute is not forwarded to an element that rejects it.
   */
  name?: string;
};

export interface CheckboxProps
  extends CheckboxOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof CheckboxOwnProps> {}

/** Custom SVG check icon — pixel-perfect centering without font metrics */
const CheckIcon = () => (
  <svg
    className="ds-checkbox__icon"
    width="14"
    height="14"
    viewBox="0 0 14 14"
    fill="none"
    aria-hidden="true"
  >
    <path
      d="M2 7.5L5.5 11L12 3"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

/** Custom SVG minus icon for indeterminate state */
const MinusIcon = () => (
  <svg
    className="ds-checkbox__icon"
    width="14"
    height="14"
    viewBox="0 0 14 14"
    fill="none"
    aria-hidden="true"
  >
    <path d="M2 7H12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
  </svg>
);

export const Checkbox = React.forwardRef<HTMLDivElement, CheckboxProps>(
  (
    {
      label,
      helperText,
      error = false,
      checked = false,
      indeterminate = false,
      disabled = false,
      size = 'default',
      onCheckedChange,
      onChange,
      className = '',
      ariaLabel,
      name: _name,
      onClick,
      onKeyDown,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-checkbox';
    const generatedId = useId();
    const helperId = helperText ? `${generatedId}-helper` : undefined;
    const describedBy = helperId ?? rest['aria-describedby'];

    const classes = [
      baseClass,
      size === 'compact' ? `${baseClass}--compact` : '',
      checked ? `${baseClass}--checked` : '',
      indeterminate && !checked ? `${baseClass}--indeterminate` : '',
      disabled ? `${baseClass}--disabled` : '',
      helperText ? `${baseClass}--has-helper` : '',
      error ? `${baseClass}--error` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const toggle = () => {
      if (disabled) return;
      onCheckedChange?.(!checked);
      onChange?.(!checked);
    };

    const handleClick = (e: React.MouseEvent<HTMLDivElement>) => {
      onClick?.(e);
      toggle();
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
      onKeyDown?.(e);
      if (e.key === ' ' || e.key === 'Enter') {
        e.preventDefault();
        toggle();
      }
    };

    return (
      <div
        {...rest}
        ref={ref}
        className={classes}
        onClick={handleClick}
        onKeyDown={handleKeyDown}
        role="checkbox"
        aria-checked={indeterminate && !checked ? 'mixed' : checked}
        aria-disabled={disabled}
        aria-label={rest['aria-label'] || ariaLabel || label}
        aria-describedby={describedBy}
        aria-invalid={error || undefined}
        tabIndex={disabled ? -1 : 0}
      >
        <div className={`${baseClass}__box`}>
          {indeterminate && !checked ? <MinusIcon /> : <CheckIcon />}
        </div>
        {/* Without a helper the label stays a bare span, so existing markup
            (and layout) is untouched; with one, label and helper stack in a
            text column beside the box. */}
        {helperText ? (
          <span className={`${baseClass}__text`}>
            {label && <span className={`${baseClass}__label`}>{label}</span>}
            <span className={`${baseClass}__helper`} id={helperId}>
              {helperText}
            </span>
          </span>
        ) : (
          label && <span className={`${baseClass}__label`}>{label}</span>
        )}
      </div>
    );
  },
);

Checkbox.displayName = 'Checkbox';

/* ============================================
   CHECKBOX GROUP — Wraps multiple Checkboxes
   ============================================ */

type CheckboxGroupOwnProps = {
  /** Group label */
  label?: string;
  /** Helper or error message rendered below the group */
  helperText?: string;
  /** Error state — recolours the helper text and marks the group invalid */
  error?: boolean;
  /** Marks the group required and renders the required marker on its label */
  required?: boolean;
  /** Checkbox options */
  items: { label: string; value: string; disabled?: boolean }[];
  /** Currently selected values */
  values?: string[];
  /** Layout direction */
  direction?: 'vertical' | 'horizontal';
  /** Component size */
  size?: 'default' | 'compact';
  /** Called with the next selected values */
  onValuesChange?: (values: string[]) => void;
  /** Additional CSS classes */
  className?: string;
  /**
   * Legacy change handler, kept for backwards compatibility.
   *
   * @deprecated Use `onValuesChange` instead.
   */
  onChange?: (values: string[]) => void;
};

export interface CheckboxGroupProps
  extends CheckboxGroupOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof CheckboxGroupOwnProps> {}

export const CheckboxGroup = React.forwardRef<HTMLDivElement, CheckboxGroupProps>(
  (
    {
      label,
      helperText,
      error = false,
      required = false,
      items,
      values = [],
      direction = 'vertical',
      size = 'default',
      onValuesChange,
      onChange,
      className = '',
      id,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-checkbox-group';
    const classes = [baseClass, `${baseClass}--${direction}`, className]
      .filter(Boolean)
      .join(' ');

    /* Same derivation Field applies internally to the same id, so the
       aria-labelledby / aria-describedby pointers below land on the label
       and helper Field renders. */
    const generatedId = useId();
    const groupId = id || generatedId;
    const labelId = label ? `${groupId}-label` : undefined;
    const describedBy = helperText ? `${groupId}-helper` : rest['aria-describedby'];

    const handleToggle = (itemValue: string) => {
      const next = values.includes(itemValue)
        ? values.filter((v) => v !== itemValue)
        : [...values, itemValue];
      onValuesChange?.(next);
      onChange?.(next);
    };

    return (
      <Field
        {...rest}
        ref={ref}
        className={classes}
        group
        label={label}
        helperText={helperText}
        error={error}
        required={required}
        /* size deliberately not forwarded: Field's compact modifier would
           shrink the group label, which the old group markup never did —
           compact here sizes the child checkboxes only, as before. */
        id={groupId}
        role="group"
        aria-labelledby={labelId}
        aria-describedby={describedBy}
        aria-invalid={error || undefined}
      >
        <div className={`${baseClass}__items`}>
          {items.map((item) => (
            <Checkbox
              key={item.value}
              label={item.label}
              checked={values.includes(item.value)}
              disabled={item.disabled}
              size={size}
              onCheckedChange={() => handleToggle(item.value)}
            />
          ))}
        </div>
      </Field>
    );
  },
);

CheckboxGroup.displayName = 'CheckboxGroup';
